var $bm_rt;
var dropDownIndex = effect('Lock Anchor Point To...')(1).value;
var when = effect('When to Sample')(1);
switch (dropDownIndex) {
case 1:
    var L = thisLayer.sourceRectAtTime(when);
    var x = $bm_sum(L.left, $bm_div(L.width, 2));
    var y = $bm_sum(L.top, $bm_div(L.height, 2));
    $bm_rt = [
        x,
        y
    ];
    break;
case 2:
    var L = thisLayer.sourceRectAtTime(when);
