case 8:
    var L = thisLayer.sourceRectAtTime(when);
    var x = L.left;
    var y = $bm_sum(L.top, L.height);
    $bm_rt = [
        x,
        y
    ];
    break;
case 9:
    var L = thisLayer.sourceRectAtTime(when);
    var x = $bm_sum(L.left, L.width);
    var y = $bm_sum(L.top, L.height);
    $bm_rt = [
        x,
        y
    ];
    break;
default:
